fields.InputDefinition:
{
  "goal": "Navigate to Data Explorer and open the Members entity to see the records grid. Then click on a specific member record to open its Full Record using the `Open Full Record` button. Verify that the detail form displays with populated fields such as Name, Email, Organization, or Membership Type.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Member detail form is displayed with populated fields",
    "Fields like Name, Email, or Organization are visible and have values"
  ]
}
